"""RelayVSR upscaling at the checkpoints' native x4 or x2: a keyframe every 15 frames generated by the keyframe model, each window of 16 frames
decoded from its two keyframes (the window's first frame, the previous window's last, decoded again for the video history and not emitted
twice)."""
from __future__ import annotations

import gc
from dataclasses import dataclass

import torch
import torch.nn.functional as F
from accelerate import init_empty_weights
from mmgp import offload
from tqdm import tqdm

from postprocessing.memory import minimal_vram
from shared.utils import offload_registry
from shared.utils.media_control import controlled_model_loading, loading_callback
from .decoder import TOKEN_PIXELS, RelayVSRDecoder, Stream, previous_frame_rotation, rope_table
from .keyframes import LATENT_CHANNELS, SPATIAL_FACTOR, RelayVSRKeyframeModel

WINDOW_FRAMES = 16  # each window: a keyframe, 14 frames, the next keyframe
DTYPE = torch.bfloat16


@dataclass(frozen=True)
class RelayVSRPaths:
    keyframes: str
    decoder: str
    scale: int  # the checkpoints' native upscaling, 4 or 2


def kv_cache_bytes(height, width, padding):
    """The INT8 keyframe cache of a source of height x width pixels (padding: its pixels per keyframe token): 30 layers, 4 keyframes, keys
    and values of 3072 channels per token, with a FP16 scale per 32."""
    return -(-height // padding) * -(-width // padding) * 30 * 4 * 2 * 3072 * (1 + 1 / 16)


def _report(progress_callback, phase, current=None, total=None, unit=None):
    if callable(progress_callback):
        progress_callback(phase, current, total, unit)


class RelayVSRRuntime:
    def __init__(self):
        self.keyframes = self.decoder = self.offloadobj = self.loaded = None

    @controlled_model_loading
    def load(self, paths: RelayVSRPaths, *, init_pipe, profile) -> None:
        if self.keyframes is not None and self.loaded == (paths, profile):
            return
        self.release()
        if not torch.cuda.is_available():
            raise RuntimeError("RelayVSR requires CUDA.")
        with init_empty_weights(include_buffers=True):
            keyframes, decoder = RelayVSRKeyframeModel(paths.scale), RelayVSRDecoder(paths.scale)
        offload.load_model_data(keyframes, paths.keyframes, writable_tensors=False, default_dtype=DTYPE, pre_load_callback=lambda model: model.lock_layers_dtypes(DTYPE), verboseLevel=-1)
        keyframes.apply_post_init_changes()
        offload.load_model_data(decoder, paths.decoder, writable_tensors=False, default_dtype=DTYPE, verboseLevel=-1)
        for model in (keyframes, decoder):
            model.eval().requires_grad_(False)
        pipe = {"transformer": keyframes, "decoder": decoder}
        kwargs = {"coTenantsMap": {"transformer": ["decoder"], "decoder": ["transformer"]}}
        profile_no = init_pipe(pipe, kwargs, profile)
        self.cache_in_ram = minimal_vram(kwargs)  # Postprocessor VRAM Usage: Minimum keeps the keyframe memory in RAM
        self.offloadobj = offload.profile(pipe, loading_callback=loading_callback(), profile_no=profile_no, quantizeTransformer=False, convertWeightsFloatTo=DTYPE, verboseLevel=-1, **kwargs)
        offload_registry.register_offloadobj("RelayVSR", self.offloadobj, self.release)
        self.keyframes, self.decoder, self.loaded = keyframes, decoder, (paths, profile)

    def release(self) -> None:
        if self.offloadobj is not None:
            offload_registry.unregister_offloadobj("RelayVSR", self.offloadobj)
            self.offloadobj.release()
        self.keyframes = self.decoder = self.offloadobj = self.loaded = None
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

    @torch.inference_mode()
    def upscale(self, sample: torch.Tensor, scale: float, *, seed: int = 0, abort_callback=None, progress_callback=None):
        """sample (3, frames, height, width), uint8 or float in [-1, 1]: the upscaled frames, uint8 (3, frames, int(height * scale),
        int(width * scale)) in RAM, computed at the checkpoints' native scale and resized to the scale; None when aborted."""
        if self.keyframes is None:
            raise RuntimeError("RelayVSR models are not loaded.")
        from models.wan.modules.posemb_layers import set_use_fp32_rope_freqs
        set_use_fp32_rope_freqs(True)
        device = torch.device("cuda", torch.cuda.current_device())
        frame_count, (height, width) = sample.shape[1], sample.shape[-2:]
        native = self.keyframes.scale
        padding = SPATIAL_FACTOR // native  # low-resolution pixels per keyframe token
        padded_height, padded_width = height + (-height) % padding, width + (-width) % padding
        output_height, output_width = max(1, int(height * scale)), max(1, int(width * scale))
        rows, columns = padded_height * native // TOKEN_PIXELS, padded_width * native // TOKEN_PIXELS  # the latents' and decoder tokens' grid
        cache = self.keyframes.new_cache(padded_height * native, padded_width * native, device, in_ram=self.cache_in_ram)
        rope, rotation = rope_table(rows, columns, device), previous_frame_rotation(device)
        generator = torch.Generator(device=device).manual_seed(int(seed))
        output = torch.empty((3, frame_count, output_height, output_width), dtype=torch.uint8, device="cpu")
        aborted = lambda: callable(abort_callback) and abort_callback()
        print(f"[RelayVSR] x{native} model, {width}x{height} -> {output_width}x{output_height}, {frame_count} frames, keyframe cache INT8 ({kv_cache_bytes(height, width, padding) / 2**30:.1f} GiB"
              + (", in RAM)" if self.cache_in_ram else ", in VRAM as far as it fits, the rest in RAM)" if cache.ring is not None else ", in VRAM)"))

        def low_resolution(index):
            frame = sample[:, index].to(device=device, dtype=torch.float32).unsqueeze(0)
            frame = frame.div_(127.5).sub_(1.0) if sample.dtype == torch.uint8 else frame.clamp_(-1.0, 1.0)
            return F.pad(frame, (0, padded_width - width, 0, padded_height - height), mode="replicate").to(DTYPE)

        def keyframe(index):
            frame = low_resolution(index)
            noise = torch.randn((1, LATENT_CHANNELS, 1, rows, columns), generator=generator, device=device, dtype=torch.float32)
            latent = self.keyframes.keyframe(frame, noise, cache, aborted)
            frame = noise = None
            return None if latent is None else self.decoder.prime(latent.to(DTYPE), rope, aborted)

        def store(index, pixels):
            pixels = pixels[..., :height * native, :width * native]
            if (output_height, output_width) != pixels.shape[-2:]:
                pixels = F.interpolate(pixels.float(), size=(output_height, output_width), mode="bicubic", antialias=True)
            output[:, index] = pixels[0].float().clamp_(-1.0, 1.0).add_(1.0).mul_(127.5).round_().to(torch.uint8).cpu()

        try:
            start, start_condition, first = 0, keyframe(0), True
            if start_condition is None:
                return None, None
            with tqdm(total=frame_count, desc="RelayVSR", unit="frame") as progress:
                while True:
                    end = min(start + WINDOW_FRAMES - 1, frame_count - 1)
                    end_condition = start_condition if end == start else keyframe(end)
                    if end_condition is None:
                        return None, None
                    stream = Stream(start_condition, end_condition, rows * columns, rows, columns, DTYPE, device)
                    for offset, index in enumerate(range(start, end + 1)):
                        pixels = self.decoder.decode(low_resolution(index), stream, rope, rotation, aborted)
                        if pixels is None:
                            return None, None
                        if first or offset:
                            store(index, pixels)
                            progress.update()
                            _report(progress_callback, "RelayVSR - Upscaling Frames", progress.n, frame_count, "frames")
                        pixels = None
                    stream.release()
                    first = False
                    if end == frame_count - 1:
                        return output, None
                    start, start_condition = end, end_condition
        finally:
            cache.release()


_RUNTIME = RelayVSRRuntime()


def load_models(paths: RelayVSRPaths, *, init_pipe, profile):
    _RUNTIME.load(paths, init_pipe=init_pipe, profile=profile)


def upscale_video(sample, scale, **kwargs):
    return _RUNTIME.upscale(sample, scale, **kwargs)


def release_models():
    _RUNTIME.release()


__all__ = ["RelayVSRPaths", "load_models", "release_models", "upscale_video"]
